TEST_CASE("D111 Native startup and scoped construction port destruction are passive") {
    CHECK(native_test::clocks == 0);
    for (unsigned i = 0; i < 5; ++i) CHECK(native_test::calls[i] == 0);
    const auto heaps = allocations::calls;
    { Guard guard; imu_heading_bench::Native local; const auto port = local.port(); (void)port; }
    CHECK(native_test::clocks == 0);
    for (unsigned i = 0; i < 5; ++i) CHECK(native_test::calls[i] == 0);
    CHECK(allocations::calls == heaps);
}
